/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { CircularApertureScreen } from "../../src/circular-aperture/CircularApertureScreen.js";
import DiffractionLabColors from "../../src/DiffractionLabColors.js";
import { GratingsScreen } from "../../src/gratings/GratingsScreen.js";
import { HolographyScreen } from "../../src/holography/HolographyScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { ResolvingPowerScreen } from "../../src/resolving-power/ResolvingPowerScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  const screens = [
    new GratingsScreen({
      name: stringManager.getScreenNames().gratingsStringProperty,
      tandem: Tandem.ROOT.createTandem("gratingsScreen"),
      backgroundColorProperty: DiffractionLabColors.backgroundColorProperty,
    }),
    new ResolvingPowerScreen({
      name: stringManager.getScreenNames().resolvingPowerStringProperty,
      tandem: Tandem.ROOT.createTandem("resolvingPowerScreen"),
      backgroundColorProperty: DiffractionLabColors.backgroundColorProperty,
    }),
    new CircularApertureScreen({
      name: stringManager.getScreenNames().circularApertureStringProperty,
      tandem: Tandem.ROOT.createTandem("circularApertureScreen"),
      backgroundColorProperty: DiffractionLabColors.backgroundColorProperty,
    }),
    new HolographyScreen({
      name: stringManager.getScreenNames().holographyStringProperty,
      tandem: Tandem.ROOT.createTandem("holographyScreen"),
      backgroundColorProperty: DiffractionLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { DiffractionLabColors, stringManager } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
